{"files": {"app.mjs": "import { legalMoves, applyMove, isSolved } from './engine.mjs';
import { renderBoard } from './render.mjs';

let puzzles = [];
let currentPuzzle = null;
let pegs = [];
let selected = null;
let history = [];
let solution = [];
let solutionIndex = 0;

async function init() {
  const res = await fetch('puzzles.json');
  puzzles = await res.json();
  const choice = document.getElementById('board-choice');
  puzzles.forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.id;
    opt.textContent = p.title;
    choice.appendChild(opt);
  });
  choice.addEventListener('change', () => loadPuzzle(choice.value));
  document.getElementById('board').addEventListener('click', handleClick);
  document.getElementById('undo').addEventListener('click', undo);
  document.getElementById('restart').addEventListener('click', restart);
  document.getElementById('hint').addEventListener('click', hint);
  loadPuzzle(puzzles[0].id);
}

function loadPuzzle(id) {
  currentPuzzle = puzzles.find(p => p.id == id);
  pegs = [...currentPuzzle.start];
  selected = null;
  history = [];
  solution = [...currentPuzzle.solution];
  solutionIndex = 0;
  updateUI();
}

function handleClick(e) {
  const btn = e.target.closest('button[data-cell]');
  if (!btn) return;
  const cell = btn.dataset.cell;
  const isOccupied = pegs.includes(cell);

  if (isOccupied) {
    selected = cell;
  } else if (selected) {
    const move = findMove(selected, cell);
    if (move) {
      history.push([...pegs]);
      pegs = applyMove(currentPuzzle, pegs, move);
      selected = null;
      checkWin();
    }
  }
  updateUI();
}

function findMove(from, to) {
  const [fx, fy] = from.split(',').map(Number);
  const [tx, ty] = to.split(',').map(Number);
  const dx = tx - fx, dy = ty - fy;
  if (Math.abs(dx) !== 2 || Math.abs(dy) !== 2 || (dx !== 0 && dy !== 0)) return null;
  const mx = fx + dx / 2, my = fy + dy / 2;
  const mid = `${mx},${my}`;
  if (!pegs.includes(mid) || pegs.includes(to)) return null;
  return [from, mid, to];
}

function undo() {
  if (history.length === 0) return;
  pegs = history.pop();
  selected = null;
  updateUI();
}

function restart() {
  pegs = [...currentPuzzle.start];
  selected = null;
  history = [];
  solutionIndex = 0;
  updateUI();
}

function hint() {
  if (solutionIndex >= solution.length) return;
  const copyStart = [...currentPuzzle.start];
  let state = [...copyStart];
  for (let i = 0; i < solutionIndex; i++) {
    state = applyMove(currentPuzzle, state, solution[i]);
  }
  const targetState = applyMove(currentPuzzle, state, solution[solutionIndex]);
  if (arraysEqual(new Set(pegs), new Set(state))) {
    selected = solution[solutionIndex][0];
    updateUI();
    solutionIndex++;
  } else {
    alert('Restart to align with the solution path.');
  }
}

function arraysEqual(a, b) {
  if (a.size !== b.size) return false;
  for (const item of a) {
    if (!b.has(item)) return false;
  }
  return true;
}

function checkWin() {
  if (isSolved(currentPuzzle, pegs)) {
    document.getElementById('status').textContent = 'Solved';
  }
}

function updateUI() {
  const targets = selected ? legalMoves(currentPuzzle, pegs).filter(m => m[0] === selected).map(m => m[2]) : [];
  renderBoard(currentPuzzle, pegs, selected, targets);
  document.getElementById('counter').textContent = `Moves: ${history.length} / ${currentPuzzle.start.length - currentPuzzle.goal.length}`;
  if (!isSolved(currentPuzzle, pegs)) {
    document.getElementById('status').textContent = '';
  }
}

init();"}}
